const L = (r: R, t: number) => r[0] + (r[1] - r[0]) * t;
const cl = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));
const r0 = (r: R, t: number) => Math.round(L(r, t));
const r2 = (v: number) => Math.round(v * 100) / 100;

type Ov = Partial<MilitaryDesign>;
const INF = C.Infantry, MECH = C.Mechanized, ARM = C.Armor, ART = C.Artillery, ROC = C.RocketArtillery, AD = C.AirDefense,
  REC = C.Recon, SOF = C.SpecialForces, ENG = C.Engineers, MSL = C.MissileLauncher, FGT = C.Fighter, MRL = C.Multirole,
  STK = C.Strike, BMB = C.Bomber, HEL = C.Helicopter, TRN = C.AirTransport, DRN = C.Drone, PAT = C.PatrolBoat,
  FFG = C.Frigate, DDG = C.Destroyer, CVN = C.Carrier, SUB = C.Submarine, AMP = C.Amphibious;
const W: Ov = { mobility: 'wheeled' };
const WS: Ov = { mobility: 'wheeled', armor: 'soft' };

/** Current (in service by 2030) design. t = tier 0..1 within its category profile. */
function D(id: string, name: string, cat: C, origin: string, year: number, t: number, description: string, o: Ov = {}): MilitaryDesign {
  const p = PROF[cat];
  const air = cat >= C.Fighter && cat <= C.Drone;
  const sec = (v: number) => cl(Math.round(v), 0, 100);
  const base: MilitaryDesign = {
    id, name, category: cat, origin, year, future: false, exportable: true,
    armor: p.arm, mobility: p.mob, personnel: p.pers,
    attackSoft: sec(L(p.s, t)), attackHard: sec(L(p.h, t)), attackAir: sec(L(p.a, t)), attackNaval: sec(L(p.n, t)), attackSub: sec(L(p.sb, t)),
    rangeGround: r0(p.rg, t), rangeAir: r0(p.ra, t), rangeNaval: r0(p.rn, t),
    defenseGround: sec(L(p.dg, t)), defenseAir: sec(L(p.da, t)), defenseNaval: sec(L(p.dn, t)),
    speedKmh: r0(p.spd, t), spotting: r0(p.spot, t), stealth: cl(r2(L(p.st, t)), 0, 0.95),
    rangeKm: air ? r0(p.rk, t) : 0, fuelCapacity: p.fuel,
    cost: Math.round(L(p.cost, t) / 10) * 10, militaryGoodsCost: r0(p.mg, t), buildDays: r0(p.days, t), upkeep: r2(L(p.up, t)),
    indirect: !!p.ind, canCapture: !!p.cap, description,
  };
  return { ...base, ...o };
}
/** Future design: not in service by 2030. */
function F(id: string, name: string, cat: C, origin: string, year: number, t: number, rc: number, pred: string | undefined, description: string, o: Ov = {}): MilitaryDesign {
  return D(id, name, cat, origin, year, t, description, { future: true, researchCost: rc, predecessor: pred, exportable: false, ...o });
}

