// ---------------------------------------------------------------- inventories (1 Jan 2030)
function N(code: string, units: Record<string, number>, produces: string[] = []): NationInventory {
  const inf = `${code.toLowerCase()}_infantry_bn`;
  const list = Object.entries(units).filter(([, c]) => c > 0).map(([id, count]) => ({ id: id === "INF" ? inf : id, count }));
  return { code, units: list, produces: produces.map((p) => (p === "INF" ? inf : p)) };
}

